function end(s,i,a,b){if(s[i]!==a)throw Error("opening");let n=0;for(let j=i;j<s.length;j++){if(s[j]===a)n++;else if(s[j]===b&&--n===0)return j;}throw Error("unbalanced");}
function mask(s){let o=s.split(""),i=0,state="code",depth=0,raw=0;const blank=j=>{if(s[j]!=="\n")o[j]=" ";};while(i<s.length){let c=s[i],n=s[i+1]??"";if(state==="code"){if(c==="/"&&n==="/"){blank(i++);blank(i++);state="line";continue;}if(c==="/"&&n==="*"){blank(i++);blank(i++);depth=1;state="block";continue;}if(c==='"'){blank(i++);state="string";continue;}if(c==="'"&&i+2<s.length&&(s[i+1]==="\\"?i+3<s.length&&s[i+3]==="'":s[i+2]==="'")){blank(i++);state="char";continue;}if(c==="r"){const m=/^r(#{0,255})"/.exec(s.slice(i));if(m){raw=m[1].length;for(let k=0;k<m[0].length;k++)blank(i++);state="raw";continue;}}i++;continue;}if(state==="line"){if(c==="\n")state="code";else blank(i);i++;continue;}if(state==="block"){if(c==="/"&&n==="*"){blank(i++);blank(i++);depth++;}else if(c==="*"&&n==="/"){blank(i++);blank(i++);if(--depth===0)state="code";}else blank(i++);continue;}if(state==="string"||state==="char"){const d=state==="string"?'"':"'";if(c==="\\"){blank(i++);if(i<s.length)blank(i++);}else{blank(i++);if(c===d)state="code";}continue;}if(state==="raw"){const term='"'+"#".repeat(raw);if(s.startsWith(term,i)){for(let k=0;k<term.length;k++)blank(i++);state="code";}else blank(i++);continue;}throw Error("state");}return o.join("");}
function cfg(s){s=s.trim();if(s==="test")return false;const m=/^(all|any|not)\s*\((.*)\)$/s.exec(s);if(!m)return null;let depth=0,start=0,args=[];for(let i=0;i<m[2].length;i++){if(m[2][i]==="(")depth++;else if(m[2][i]===")")depth--;else if(m[2][i]===","&&depth===0){args.push(m[2].slice(start,i));start=i+1;}}if(m[2].slice(start).trim())args.push(m[2].slice(start));const vs=args.map(cfg);if(m[1]==="not")return vs.length===1&&vs[0]!==null?!vs[0]:null;if(m[1]==="all")return vs.includes(false)?false:vs.every(v=>v===true)?true:null;return vs.includes(true)?true:vs.every(v=>v===false)?false:null;}
function itemEnd(s,start){if(/^(?:pub(?:\([^)]*\))?\s+)?\w+\s*:(?!:)/.test(s.slice(start))){let p=0,k=0,b=0,a=0;for(let i=start;i<s.length;i++){const c=s[i];if(c==="(")p++;else if(c===")"&&p)p--;else if(c==="[")k++;else if(c==="]"&&k)k--;else if(c==="{")b++;else if(c==="}"&&b)b--;else if(c==="}"&&!p&&!k&&!a)return i-1;else if(c==="<"&&!p&&!k&&!b)a++;else if(c===">"&&a)a--;else if(c===","&&!p&&!k&&!b&&!a)return i;}throw Error("field");}let p=0,k=0;for(let i=start;i<s.length;i++){const c=s[i];if(c==="(")p++;else if(c===")"&&p)p--;else if(c==="[")k++;else if(c==="]"&&k)k--;else if(!p&&!k&&c===";")return i;else if(!p&&!k&&c==="{")return end(s,i,"{","}");}throw Error("item");}
function stripTest(s){const o=s.split("");let i=0;while(i<s.length){const start=s.indexOf("#[",i);if(start<0)break;const ae=end(s,start+1,"[","]");const m=/^#\[\s*cfg\s*\((.*)\)\s*\]$/s.exec(s.slice(start,ae+1));if(!m||cfg(m[1])!==false){i=ae+1;continue;}let j=ae+1;while(true){while(/\s/.test(s[j]??"")&&j<s.length)j++;if(!s.startsWith("#[",j))break;j=end(s,j+1,"[","]")+1;}const ie=itemEnd(s,j);for(let x=start;x<=ie;x++)if(s[x]!=="\n")o[x]=" ";i=ie+1;}return o.join("");}
function aliases(code,target){return [...code.matchAll(new RegExp("\\b"+target+"\\s+as\\s+(\\w+)","g")),...code.matchAll(new RegExp("\\btype\\s+(\\w+)\\s*=\\s*(?:\\w+::)*"+target+"\\s*;","g"))].map(x=>x[1]);}
function fields(index,target){const as=new Set([target]);while(true){let added=0;for(const {code} of index)for(const n of Array.from(as))for(const a of aliases(code,n))if(!as.has(a)){as.add(a);added++;}if(!added)break;}const fs=[];for(const {path,code:raw} of index){let code=raw;for(const a of as)if(a!==target)code=code.replace(new RegExp("\\b"+a+"\\b","g"),target);if(!code.includes(target))continue;for(const m of code.matchAll(/\bstruct\s+(\w+)(?:\s*<[^{};]*>)?\s*\{/g)){const e=end(code,m.index+m[0].length-1,"{","}");for(const f of code.slice(m.index+m[0].length,e).matchAll(/\b(\w+)\s*:\s*([^,;{}]+)/g)){if(new RegExp("\\b"+target+"\\b").test(f[2]))fs.push({owner:m[1],field:f[1],type:target,path});}}}return{aliases:Array.from(as),fields:fs};}
return {end,mask,cfg,itemEnd,stripTest,fields};
